class BrowserEventsClient extends Context.Service<
  BrowserEventsClient,
  {
    readonly events: OtlpEvents["Service"];
    readonly allowed: () => boolean;
    readonly context: (
      name: string,
      properties?: EventAttributes,
    ) => EventAttributes;
  }
>()("krakstack/events/BrowserEventsClient") {}

const emit = Effect.fnUntraced(function* (
  name: string,
  properties?: EventAttributes,
  options?: BrowserEventOptions,
) {
  const client = yield* BrowserEventsClient;
  if (!client.allowed()) return;
  const decoded = yield* Schema.decodeUnknownEffect(BrowserEventOptions)(
    options ?? {},
  );
  yield* event(
    name,
    { ...properties, ...client.context(name, properties) },
    decoded,
  ).pipe(Effect.provideService(OtlpEvents, client.events));
});

const page = Effect.fnUntraced(function* (input: BrowserPageOptions = {}) {
  const client = yield* BrowserEventsClient;
  if (!client.allowed()) return;
  const decoded = yield* Schema.decodeUnknownEffect(BrowserPage)(input);
  const properties = eventProperties(decoded.properties);
  if (decoded.name) properties["analytics.page.name"] = decoded.name;
  if (decoded.category)
    properties["analytics.page.category"] = decoded.category;
  properties["url.path"] =
    (decoded.path ?? location.pathname).split(/[?#]/, 1)[0] ?? "/";
  yield* emit("browser.page_view", properties, decoded.options);
});

const clients: Array<BrowserEventsClient["Service"]> = [];
const runBrowser = (
  program: Effect.Effect<void, Schema.SchemaError, BrowserEventsClient>,
) =>
  Effect.suspend(() => {
    const client = clients.at(-1);
    return client
      ? program.pipe(Effect.provideService(BrowserEventsClient, client))
      : Effect.void;
  });

const BrowserClientLive = Layer.effectDiscard(
  Effect.gen(function* () {
    const client = yield* BrowserEventsClient;
    yield* Effect.acquireRelease(
      Effect.sync(() => {
        clients.push(client);
        return client;
      }),
      (client) =>
        Effect.sync(() => {
          const index = clients.indexOf(client);
          if (index !== -1) clients.splice(index, 1);
        }),
    );
  }),
);

const pageViewListeners = new Set<() => void>();
let stopPageViewTracking: (() => void) | undefined;

const subscribePageViews = (listener: () => void) => {
  if (pageViewListeners.size === 0) {
    const pushState = history.pushState;
    const replaceState = history.replaceState;
    const notify = () => {
      for (const onPage of pageViewListeners) onPage();
    };
    const trackedPushState: History["pushState"] = (...args) => {
      pushState.apply(history, args);
      notify();
    };
    const trackedReplaceState: History["replaceState"] = (...args) => {
      replaceState.apply(history, args);
      notify();
    };
    history.pushState = trackedPushState;
    history.replaceState = trackedReplaceState;
    globalThis.addEventListener("popstate", notify);
    stopPageViewTracking = () => {
      globalThis.removeEventListener("popstate", notify);
      if (history.pushState === trackedPushState) history.pushState = pushState;
      if (history.replaceState === trackedReplaceState)
        history.replaceState = replaceState;
    };
  }
  pageViewListeners.add(listener);
  return () => {
    pageViewListeners.delete(listener);
    if (pageViewListeners.size === 0) {
      stopPageViewTracking?.();
      stopPageViewTracking = undefined;
    }
  };
};

const BrowserPageViewsLive = Layer.effectDiscard(
  Effect.gen(function* () {
    const fibers = yield* FiberSet.make();
    const run = yield* FiberSet.runtime(fibers)<BrowserEventsClient>();
    let previousPath = location.pathname;
    yield* Effect.acquireRelease(
      Effect.sync(() =>
        subscribePageViews(() => {
          const path = location.pathname;
          if (path === previousPath) return;
          previousPath = path;
          run(page({ path }).pipe(Effect.ignore));
        }),
      ),
      (unsubscribe) => Effect.sync(unsubscribe),
    );
    yield* page({ path: previousPath }).pipe(Effect.ignore);
    yield* Effect.acquireRelease(
      Effect.sync(() => {
        let allowed = analyticsAllowed();
        return subscribeAnalyticsConsent(() => {
          const active = analyticsAllowed();
          if (active && !allowed) run(page().pipe(Effect.ignore));
          allowed = active;
        });
      }),
      (unsubscribe) => Effect.sync(unsubscribe),
    );
  }),
);

export class BrowserEvents {
  static readonly track = (
    name: string,
    properties?: EventAttributes,
    options?: BrowserEventOptions,
  ) => runBrowser(emit(name, eventProperties(properties), options));
  static readonly page = (options?: BrowserPageOptions) =>
    runBrowser(page(options));

  /** Requires BrowserOtlp; no identifiers are persisted. */
  static readonly layer = ({
    enabled = true,
    requireConsent = true,
    respectDoNotTrack = true,
    pageViews = true,
    locale,
    sanitizePath,
  }: BrowserEventsOptions = {}) => {
    const allowed = () =>
      enabled &&
      (!respectDoNotTrack || !browserPrivacyEnabled()) &&
      (!requireConsent || analyticsAllowed());
    let previousPath: string | undefined;
    let pageViewId = crypto.randomUUID();
    const context = (
      name: string,
      properties?: EventAttributes,
    ): EventAttributes => {
      const explicitPath = Schema.decodeUnknownOption(Schema.String)(
        properties?.["url.path"],
      );
      const path = Option.getOrElse(explicitPath, () => location.pathname);
      if (location.pathname !== previousPath || name === "browser.page_view") {
        previousPath = location.pathname;
        pageViewId = crypto.randomUUID();
      }
      const attributes = {
        "app.event.schema.version": "1",
        "analytics.page_view.id": pageViewId,
        "log.record.uid": crypto.randomUUID(),
        "url.path": sanitizePath?.(path) ?? path,
        "browser.language": navigator.language.slice(0, 256),
      };
      const optional: Record<string, string> = {};
      if (locale) optional["analytics.locale"] = locale();
      if (document.referrer) {
        const referrer = URL.parse(document.referrer);
        if (referrer && referrer.hostname !== location.hostname)
          optional["url.referrer"] = referrer.hostname;
      }
      const search = new URLSearchParams(location.search);
      for (const key of ["source", "medium", "campaign", "content", "term"]) {
        const value = search.get(`utm_${key}`);
        if (value) optional[`utm.${key}`] = value.slice(0, 256);
      }
      return { ...attributes, ...optional };
    };
    const client = Layer.effect(
      BrowserEventsClient,
      Effect.gen(function* () {
        const exporter = yield* OtlpEvents;
        return {
          allowed,
          events: {
            push: (record: Parameters<typeof exporter.push>[0]) => {
              if (allowed())
                exporter.push({
                  ...record,
                  canExport: requireConsent ? analyticsExportGuard() : allowed,
                  scopeName: "krakstack.application.events",
                });
            },
          },
          context,
        };
      }),
    );
    const browser = Layer.mergeAll(
      BrowserClientLive,
      enabled && pageViews ? BrowserPageViewsLive : Layer.empty,
    ).pipe(Layer.provideMerge(client));
    return browser;
  };
}

import type { ReactNode } from "react";
import { ListFilterIcon } from "lucide-react";
import {
  DataTable,
  DataTableReferenceCell,
  type DataTableColDef,
  type DataTableStatus,
  type DataTableReferenceItem,
} from "@/components/ui/data-table";
import { useKrakstackLocale } from "@/components/ui/krakstack-provider";
import {
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarGroup,
  MenubarItem,
} from "@/components/ui/menubar";
import type { EventLogRecord, EventQuery } from "../schema";
import { eventTextAttribute } from "../record";

const translations = {
  en: {
    title: "Activity history",
    event: "Action",
    allEvents: "All actions",
    time: "Time",
    action: "Action",
    target: "Target",
    actor: "Actor",
    method: "Method",
    actorMember: "Member",
    impersonatedBy: "Impersonated by",
    actorOrganization: "Organization",
    methodApiKey: "API Key",
    methodSession: "User session",
    methodUnknown: "Unknown",
  },
  fr: {
    title: "Historique d’activité",
    event: "Action",
    allEvents: "Toutes les actions",
    time: "Date",
    action: "Action",
    target: "Cible",
    actor: "Acteur",
    method: "Méthode",
    actorMember: "Membre",
    impersonatedBy: "Identité empruntée par",
    actorOrganization: "Organisation",
    methodApiKey: "Clé API",
    methodSession: "Session utilisateur",
    methodUnknown: "Inconnue",
  },
};
export type AuditLogMessages = typeof translations.en;
export type AuditLogTableProps = DataTableStatus & {
  /** Full application-owned event catalog, with localized display labels. */
  events?: readonly { value: string; label: string }[];
  state?: EventQuery;
  onStateChange?: (state: EventQuery) => void;
  entries: readonly EventLogRecord[];
  /** Total matching records from the query response; paging lives in state. */
  rowCount: number;
  /** Display time zone for the dateTime column. Defaults to America/New_York. */
  timeZone?: string;
  /** Overrides the shared KrakstackProvider locale when supplied. */
  locale?: string;
  messages?: Readonly<Record<string, Partial<AuditLogMessages>>>;
  renderAction?: (entry: EventLogRecord) => ReactNode;
};

export const AuditLogTable = ({
  entries,
  events = [],
  rowCount,
  timeZone = "America/New_York",
  locale: localeOverride,
  messages,
  renderAction,
  state,
  onStateChange,
  ...status
}: AuditLogTableProps) => {
  const locale = useKrakstackLocale(localeOverride);
  const base = locale.split("-")[0];
  const labels = {
    ...translations.en,
    ...(base === "fr" ? translations.fr : translations.en),
    ...messages?.[base],
    ...messages?.[locale],
  };
  const methods = new Map([
    ["session", labels.methodSession],
    ["api_key", labels.methodApiKey],
  ]);
  const getActor = (entry: EventLogRecord): DataTableReferenceItem => {
    const type = eventTextAttribute(entry, "app.actor.type");
    const id =
      eventTextAttribute(entry, "app.actor.id") ??
      eventTextAttribute(entry, "user.id");
    if (type === "organization") {
      return { label: labels.actorOrganization, description: id };
    }
    if (type === "user" || eventTextAttribute(entry, "user.id") !== null) {
      const fullName = eventTextAttribute(entry, "user.full_name");
      const name = eventTextAttribute(entry, "user.name");
      const email = eventTextAttribute(entry, "user.email");
      return {
        label: fullName || name || email || labels.actorMember,
        description: fullName || name ? email || id : id,
      };
    }
    return { label: type ?? labels.actor, description: id };
  };
  const columns: DataTableColDef<EventLogRecord>[] = [
    {
      colId: "time",
      headerName: labels.time,
      type: "dateTime",
      typeOptions: { timeZone },
      valueGetter: ({ data }) =>
        new Date(Number(BigInt(data.timeUnixNano) / 1_000_000n)),
    },
    {
      field: "eventName",
      headerName: labels.action,
      cellRenderer: ({ data }) =>
        renderAction?.(data) ??
        events.find((event) => event.value === data.eventName)?.label ??
        data.eventName,
    },
    {
      colId: "record",
      headerName: labels.target,
      type: "reference",
      typeOptions: {
        imageVariant: "square",
        getItem: (entry) => {
          const id = eventTextAttribute(entry, "app.audit.target.id");
          const name = eventTextAttribute(entry, "app.audit.target.name");
          const type = eventTextAttribute(entry, "app.audit.target.type");
          return id === null
            ? null
            : {
                label: name && name !== id ? name : type || labels.target,
                description:
                  name && name !== id && type ? `${type} · ${id}` : id,
              };
        },
      },
    },
    {
      colId: "actor",
      headerName: labels.actor,
      sortable: false,
      type: "reference",
      typeOptions: {
        getItem: getActor,
      },
      cellRenderer: ({ data }) => {
        const impersonatorId = eventTextAttribute(
          data,
          "app.auth.impersonator.id",
        );
        return (
          <div className="flex min-w-0 flex-col gap-1">
            <DataTableReferenceCell item={getActor(data)} />
            {impersonatorId !== null ? (
              <span className="text-muted-foreground text-xs">
                {labels.impersonatedBy}: {impersonatorId}
              </span>
            ) : null}
          </div>
        );
      },
    },
    {
      colId: "method",
      headerName: labels.method,
      sortable: false,
      valueGetter: ({ data }) => {
        const method = eventTextAttribute(data, "app.auth.method");
        return method === null
          ? labels.methodUnknown
          : (methods.get(method) ?? labels.methodUnknown);
      },
    },
  ];
  return (
    <section aria-label={labels.title} className="flex flex-col gap-4">
      <DataTable
        locale={locale}
        status={status}
        state={state}
        onStateChange={
          onStateChange
            ? (next) =>
                onStateChange({
                  ...next,
                  eventName: state?.eventName,
                })
            : undefined
        }
        features={{
          toolbar:
            state && onStateChange
              ? {
                  items: (
                    <MenubarMenu>
                      <MenubarTrigger>
                        <ListFilterIcon
                          aria-hidden="true"
                          data-icon="inline-start"
                        />
                        {labels.event}
                        {state.eventName
                          ? `: ${events.find((event) => event.value === state.eventName)?.label ?? state.eventName}`
                          : ""}
                      </MenubarTrigger>
                      <MenubarContent className="w-80">
                        <MenubarGroup>
                          <MenubarItem
                            onClick={() =>
                              onStateChange({
                                ...state,
                                eventName: undefined,
                                page: 0,
                              })
                            }
                          >
                            {labels.allEvents}
                          </MenubarItem>
                          {events.map((event) => (
                            <MenubarItem
                              key={event.value}
                              onClick={() =>
                                onStateChange({
                                  ...state,
                                  eventName: event.value,
                                  page: 0,
                                })
                              }
                            >
                              {event.label}
                            </MenubarItem>
                          ))}
                        </MenubarGroup>
                      </MenubarContent>
                    </MenubarMenu>
                  ),
                }
              : false,
          pagination: { mode: "server", rowCount },
        }}
        columnDefs={columns}
        rowData={entries}
        getRowId={(entry) =>
          eventTextAttribute(entry, "log.record.uid") ??
          `${entry.timeUnixNano}:${entry.eventName}`
        }
      />
    </section>
  );
};

import { useState, useSyncExternalStore } from "react";
